import java.util.concurrent.Executor;

public final class CaptureCoordinator {
    public enum Phase { IDLE, RUNNING, DONE, UNKNOWN }
    @FunctionalInterface public interface Driver { void capture(Runnable captured); }
    @FunctionalInterface public interface View { void captured(); }

    private final Driver driver;
    private final Executor completion;
    private final View view;
    private Phase phase = Phase.IDLE;

    public CaptureCoordinator(Driver driver, Executor completion, View view) {
        this.driver = driver;
        this.completion = completion;
        this.view = view;
    }
    public Phase phase() { return phase; }
    public void request() {
        if (phase != Phase.IDLE) return;
        try {
            driver.capture(() -> completion.execute(this::captured));
            phase = Phase.RUNNING;
        } catch (RuntimeException failure) {
            phase = Phase.UNKNOWN;
            throw failure;
        }
    }
    private void captured() {
        phase = Phase.DONE;
        view.captured();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.Executor;
import java.util.concurrent.RejectedExecutionException;

public interface Delivery extends Executor {
    void drain();

    final class Inline implements Delivery {
        public void execute(Runnable task) { task.run(); }
        public void drain() {}
    }
    final class Queued implements Delivery {
        private final Deque<Runnable> pending = new ArrayDeque<>();
        private boolean draining;
        public void execute(Runnable task) {
            if (pending.size() >= 8) throw new RejectedExecutionException("completion capacity");
            pending.addLast(task);
        }
        public void drain() {
            if (draining) return;
            draining = true;
            try {
                while (!pending.isEmpty()) pending.removeFirst().run();
            } finally {
                draining = false;
            }
        }
    }
}

public final class App {
    public static void main(String[] args) {
        Delivery delivery = Assembly.completion();
        int[] views = {0};
        CaptureCoordinator coordinator = new CaptureCoordinator(
                Runnable::run, delivery, () -> views[0]++);
        coordinator.request();
        delivery.drain();
        System.out.println("phase=" + coordinator.phase() + " views=" + views[0]);
    }
}
